class Motif {
  constructor(props) {
    this.id = props.id ?? 0;
    this.isDisplay = props.isDisplay ?? true;
    this.originX = props.originX ?? 0;
    this.originY = props.originY ?? 0;
    this.x = props.x ?? 0;
    this.y = props.y ?? 0;
    this.size = props.size ?? 100;
    this.w = props.w ?? 100;
    this.h = props.h ?? 100;
    this.scaleX = props.scaleX ?? 1.0;
    this.scaleY = props.scaleY ?? 1.0;
    this.angle = props.angle ?? 0;
    this.rotationSpeed = props.rotationSpeed ?? 0.005;
    this.rotationDirection = props.rotationDirection ?? 1;
    this.numPoints = props.numPoints ?? 300;
    this.radius = props.radius ?? 200;
    this.elements = [];
    for (let i = 0; i < this.numPoints; i++) {
      const ang = (i * TWO_PI) / this.numPoints;
      const px = this.radius * cos(ang);
      const py = this.radius * sin(ang);
      const element = new Element({
        id: i,
        x: px,
        y: py,
        angle: ang,
        radius: this.radius,
        rotationDirection: this.rotationDirection
      });
      this.elements.push(element);
    }
  }

  run = () => {
    if (!this.isDisplay) return;
    this.angle += this.rotationSpeed * this.rotationDirection;
    push();
    translate(this.originX, this.originY);
    rotate(this.angle);
    for (let i = 0; i < this.elements.length; i++) {
      const element = this.elements[i];
      const ang = (i * TWO_PI) / this.numPoints + this.angle;
      element.x = this.radius * cos(ang);
      element.y = this.radius * sin(ang);
    }
    pop();
  }

  getElement = (index) => {
    return this.elements[index];
  }

  getPosition = () => {
    return {
      x: this.originX,
      y: this.originY
    };
  }
}


